INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('183e992f-ce19-4f65-980d-897b462aa522', 'c3c3c3c3-3030-4000-8000-000000000003', 16, 'Dia 16 — Discernimento', 'Semana 3: Discernir', '{"pch": "Provai os esp\u00edritos\u2026 Nem todo pensamento que surge \u00e9 verdadeiro. Discernir \u00e9 separar.", "verse": "1Jo 4,1", "lectio": "Leia 1Jo 4,1-6. O esp\u00edrito da verdade.", "practice": "Hoje, antes de agir por impulso, pergunte: isso vem da paz ou da ansiedade?", "question": "Como voc\u00ea distingue um pensamento \u00fatil de um destrutivo?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;